const toggle=document.querySelector('.menu-toggle');
const navigation=document.querySelector('#navigation');
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open)});
const trades={building:['Show the spaces you build.','Present extensions, renovations and building services. Use project photos to show the stages and finish, with clear information about your service area.'],electrical:['Make your services easy to understand.','Explain electrical or plumbing services in plain language. Show examples of installations and repairs, and make your coverage area and contact details easy to find.'],roofing:['Put your workmanship in view.','Explain roofing, repairs and guttering services. Use your own project photos to show the work and finish, and give customers a clear next step to discuss their roof.'],outdoor:['Let customers see the transformation.','Show landscaping, patios, driveways and garden projects. Present the materials and services you offer, alongside photos of your work and the areas you cover.'],interiors:['Bring the finish into focus.','Show bathroom fitting, decorating and interior improvements. Use detailed project photos, clear descriptions of your services and a straightforward route to contact you.']};
document.querySelectorAll('[data-trade]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-trade]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');const [title,copy]=trades[button.dataset.trade];document.querySelector('#adapt-title').textContent=title;document.querySelector('#adapt-copy').textContent=copy}));
